// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function testFuzz_property(address actor, uint256 amount) public {
        // actor must be an EOA (has no code) so that transfer() to it succeeds on the reference
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);
        vm.assume(actor != address(c));
        amount = bound(amount, 0, 1e30);

        // deploy C from the EOA so owner == actor (onlyOwner passes)
        vm.prank(actor);
        c = new SimpleWallet();

        // fund the contract with exactly the (bounded) amount so withdraw cannot revert
        vm.deal(address(c), amount);

        vm.prank(actor);
        c.withdraw(amount);

        // the ether must actually have left the contract
        assertTrue(address(c).balance == 0);
    }
}
